INSERT INTO `articles` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`, `category`, `perex`, `image`) VALUES
(1, 'Manifest Svobody učení', 'manifest-svobody-uceni', '<p class=\"lead mb-4\">Dítě je člověk. Člověk je zvídavý. Neustále se učí. Učení je přirozenou součástí života. Ve snaze pochopit svět a řešit reálné problémy je každý z nás aktivní sám a od narození. Komunikovat se světem a druhými lidmi se učíme nejlépe nápodobou, hrou, neustálým překonáváním překážek, děláním mnoha chyb a možností zažít důsledky svých činů. Svět je úžasným místem, které samo od sebe odměňuje úspěchy a neustále poskytuje zpětnou vazbu na naše jednání, čímž nám ukazuje správnou cestu.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">ČLOVĚK TVOŘÍ SVŮJ ŽIVOT</h6>\r\n<p>Člověk, který převzal odpovědnost za svůj osobní rozvoj, potažmo i své okolí, si uchovává přirozenou vnitřní motivaci. Zvládne se chopit nových příležitostí a poučit se z chyb. Dokáže nalézat způsoby řešení i v obtížných situacích a činit nelehká rozhodnutí. Vytyčuje si vlastní cíle do budoucna a je schopen jich dosahovat. Má možnost dobrovolně se účastnit vztahů dle svých vlastních preferencí a přirozeně se stát respektujícím a respektovaným členem společnosti, v níž žije. Má možnost zjistit, kým doopravdy je, a být šťastný.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">OPUSŤME KONCEPT PEDAGOGIKY</h6>\r\n<p>Úloha dospělých ve vzdělávání tkví především v pochopení jejich vlastních potřeb, které jim mohou bránit být ve vztahu s dětmi autentickými. Dospělý přejímá odpovědnost za neustálý rozvoj sebe sama. Tím se pro dítě může stát inspirací hodnou následování. To je cesta, jak jít příkladem – upustit od pedagogiky, jakožto cíleného působení na druhého člověka. Další úkol spočívá ve vytváření bezpečného prostředí, které je otevřené, čestné, důvěryhodné a svobodné, takže v něm dítě může dobrovolně setrvávat a přirozeně se samo učit, pokud chce. Lidé mají právo na svůj život a rozhodování o něm; stačí nezasahovat jim do budování sebedůvěry, a tedy i do samotného procesu učení. Ponechat jim prostor k následování jejich přirozených zájmů i talentů.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">ODLUKA ŠKOLSTVÍ OD STÁTU JE ŘEŠENÍM</h6>\r\n<p>Podmínkou možnosti převzít plnou odpovědnost za své vzdělávání je svoboda učení, která v ČR není legálně možná. Cílem spolku SvobodaUčení.cz proto je, aby unschooling a další formy sebeřízeného vzdělávání byly zcela legitimní možností, nikoli něčím, s čím je potřeba se skrývat. Řešením je úplná odluka školství od státu, jež zahrnuje: zrušení povinné školní docházky a veškeré k tomu návazné legislativy, zrušení veškerých zákonů a regulací, kterými stát školám či rodičům předepisuje, jak mají děti učit a vychovávat, zrušení veřejného financování školství prostřednictvím daní a konečně zrušení všech státem certifikovaných diplomů nutných k výkonům povolání. Výsledkem je pak volný trh pracovních i vzdělávacích příležitostí, ať už ve formě školek a škol s dobrovolnou docházkou, online kurzů, přednášek, komunitních center či domácího unschoolingu. Mělo by být ponecháno na každém z nás kdy, jak, s kým a kam se rozhodneme své vlastní prostředky i čas na vzdělávání vynaložit.</p>\r\n<p><a href=\"https://www.svobodauceni.cz/manifest-svobody-uceni/\">svobodauceni.cz - Manifest Svobody učení</a></p>', 1, '2025-04-02 09:42:38', '2025-04-04 08:19:55', 'Vzdělávání', 'Dítě je člověk. Člověk je zvídavý. Neustále se učí. Učení je přirozenou součástí života.', '1743761995_dítě prozkoumává svět a je zvědavé a rádo se učí (3).jpeg'),
(2, 'Vnitřní a Vnější Motivace', 'vnitrni-a-vnejsi-motivace', '<p class=\"lead mb-4\">Za vším, co děláme, stojí určitá forma motivace. Motivace je hnací silou, která nás směřuje k dosažení určitých cílů a uspokojení našich potřeb. Existuje mnoho různých faktorů, které ovlivňují naši motivaci, ale jedna z hlavních dělí motivaci na vnitřní a vnější.</p>\r\n<p>Co nás přiměje k jednání, když nás nikdo nesleduje? Když se odkloníme od vnějšího tlaku, ponoříme se do našeho vnitřního světa a najdeme činnosti, které nás opravdu naplňují. Někdy jsou to ty nejpříjemnější věci, které nás radují a způsobují nám potěšení, protože odpovídají našim základním potřebám nebo hlubším touhám.</p>\r\n<p>Ale co když je vnitřní motivace temnějšího druhu? Někdy může být náš motiv založen na potřebě cítit se hodnotněji na úkor druhých nebo jen proto, abychom naplnili naši touhu po pozornosti. Možná si to ani neuvědomujeme. Malé dítě může hravě vystupovat, ne protože by chtělo být komediantem, ale protože touží po pozornosti, kterou nám v tu chvíli neukazuje.</p>\r\n<p>Je tu však také celá řada věcí, které děláme každý den, aniž by nás nějak zvlášť bavily. Může to být třeba udržování našeho domova, mytí zubů nebo dokonce trpělivé čekání ve frontě. Tyto činnosti mohou být nudné, ale jsou důležité - buď pro nás nebo pro někoho blízkého.</p>\r\n<p>Některé činnosti můžeme vnímat jako nezbytné, ačkoli se nám nezdají vzrušující. Děláme je, protože věříme, že je to správné, a protože se nám zdá, že je to něco, co „musíme\" udělat, a to i tehdy, když nás nikdo nesleduje nebo nás nikdo nežádá, abychom to udělali.</p>\r\n<p>Chceme-li hluboce pochopit, co pohání nás i druhé, měli bychom mít na paměti, že vnitřní motivace je hluboce zakořeněna v našich základních potřebách a v hodnotách, které jsme si osvojili a zvnitřnili.</p>\r\n<h4 class=\"mt-5\">Hnací síla</h4>\r\n<p>Když vidíme odměnu na obzoru nebo se snažíme vyhnout nepohodlí.<br>Co nás žene vpřed, když srdce a duše v tom nejsou úplně zapojeny? Jednoduše řečeno, děláme to, co by nám normálně nedávalo smysl nebo co nám nesedí. A proč? Buď proto, abychom získali nějakou odměnu nebo se vyvarovali nějaké nepříjemné situace - ať už to znamená vyhnout se kritice, konfrontaci nebo trestu. A jakmile zmizí perspektiva odměny nebo hrozba trestu? Naše motivace k vykonání té činnosti rychle mizí.</p>\r\n<p>Vnitřní a vnější motivace? Někdy je to směs obou.<br>Samozřejmě, existují chvíle, kdy je snadné rozlišit mezi tím, co děláme pro sebe, a tím, co děláme pro ostatní. Ale někdy se tyto důvody mohou zkřížit. Představte si dítě, které miluje čtení, ale dostane slib odměny za přečtenou knihu. Tím se mění hra - je motivace vnější, vnitřní, nebo obě? A co když vnější motivace zaměníme za vnitřní? To je spíše mýtus než realita. Představa, že dítě začne dělat něco samo od sebe po dostatečně dlouhém období vnější motivace, může být klamná. Vnější tlaky nemusí nutně vzbuzovat vnitřní touhu.</p>\r\n<p></p>\r\n<h4 class=\"mt-5\">Vnitřní Motivace: Co nás pohání zevnitř?</h4>\r\n<p>Vnitřní motivace je ta forma motivace, která vychází přímo z našich vlastních zájmů, cílů a vnitřních potřeb. Je to ten pocit, který cítíme, když děláme něco, co nás naplňuje radostí a uspokojením, bez ohledu na vnější odměny či tresty. Když se věnujeme činnosti z vnitřní motivace, často cítíme smysl pro dobrodružství, osobní růst a kreativitu.</p>\r\n<p></p>\r\n<h4 class=\"mt-5\">Vnější Motivace: Role odměn a trestů</h4>\r\n<p>Na druhé straně vnější motivace vychází z vnějších podnětů, jako jsou odměny, uznání a tresty. Jsou to faktory mimo nás samotných, které nás motivují k jednání.</p>\r\n<h4 class=\"mt-5\">Závěr</h4>\r\n<p>Vnitřní a vnější motivace jsou dva klíčové faktory, které ovlivňují naše chování a rozhodování. Zatímco vnitřní motivace vychází z našich osobních zájmů, hodnot a potřeb, vnější motivace se opírá o odměny a tresty.</p>', 1, '2025-04-02 23:20:25', '2025-04-04 08:17:35', 'Vzdělávání', 'Za vším, co děláme, stojí určitá forma motivace. Motivace je hnací silou, která nás směřuje k dosažení určitých cílů a uspokojení našich potřeb.', '1743761855_dítě prozkoumává svět a je zvědavé a rádo se učí (2).jpeg'),
(4, 'Unschooling podle Wikipedie', 'unschooling-podle-wikipedie', '<p class=\"lead mb-4\">Unschooling je přístup ke vzdělávání založený na přesvědčení, že vzdělávání je přirozený celoživotní proces, který probíhá v každé chvíli našeho života. Odmítá jakékoli formy moderního školního vzdělávacího systému s předem daným kurikulem. Unschooling nerozlišuje mezi žitím a učením se.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">PRINCIP</h6>\r\n<p>Děti, které jsou vychovávány v souladu s myšlenkou unschoolingu, nechodí do školy, ani jim nevymýšlí obsah vzdělávání jejich rodiče. Nemusí plnit úkoly dané osnovami a nejsou podrobovány žádnému testování, v podstatě neimitují žádné školní aktivity. Rodiče nechávají svým dětem absolutní svobodu v následování svých zájmů a v učení se svojí vlastní cestou, zároveň se jim snaží poskytnout co nejpodnětnější prostředí a podporu pro rozvoj.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">HISTORIE</h6>\r\n<p>Termín unschooling vznikl v sedmdesátých letech minulého století a jeho autorem je bývalý učitel a pedagogický teoretik John Holt. Definuje ho jako učení nesouvisející se školním prostředím. Holt byl přesvědčený o tom, že učení je přirozený proces. V rámci své učitelské profese porovnával svobodné učení dětí bez zásahu dospělého a na druhé straně negativní vliv na učení dítěte v případě, kdy je vedeno učitelem ve škole. Chtěl také odlišit unschooling od homeschoolingu – domácího vzdělávání, protože domácí vzdělávání vnímal pouze jako přesunutí vlivu učitele na rodiče. Stále se jedná o školní činnosti, pouze v domácím prostředí, zatímco unschooling odmítá působení kohokoli jiného kromě samotného dítěte. Velká část rodičů praktikující unschooling nejprve své děti vzdělávala doma a až později přirozeně přešla k unschoolingu.</p>\r\n<p></p>\r\n<p><span class=\"fw-light lh-base\">Kořeny unschoolingu můžeme vidět také v teorii odškolnění, kterou propagovali dva tzv. emancipační pedagogové – Paulo Freire a Ivan Illich. Jejich kritika školy spočívá v poukazování na nedostatky tradičních škol, mezi které patří např. přehlížení každodenních zkušeností žáků, učitelů a rodičů. Dle Illicha školy omezují přístup k vědění a vzdělání.[4]</span></p>\r\n<p></p>\r\n<h6 class=\"mt-5\">LEGISLATIVA V ČR</h6>\r\n<p>Česká republika patří mezi státy s povinnou školní docházkou, k níž se novelou 178/2016 Sb. školského zákona od září 2017 přidalo povinné předškolní vzdělávání pro všechny pětileté děti. V České republice je v současnosti povoleno plnit povinnou školní docházku individuálním způsobem § 41 školského zákona, každé takto vzdělávané dítě však musí být zapsáno v konkrétní ZŠ, jejíž ŠVP musí také dodržovat.[5] Z výše uvedeného vyplývá, že v České republice není možné unschooling legálně provozovat, protože dítě nemá svobodu volit si co, kdy, kde, jak, s kým a jakým způsobem se bude učit, ale musí plnit požadavky Rámcového vzdělávacího programu MŠMT ČR, potažmo školního vzdělávacího programu konkrétní školy.</p>\r\n<p></p>\r\n<h6 class=\"mt-5\">ŠKOLY</h6>\r\n<p>Pro rodiče, kteří chtějí, aby si jejich dítě mohlo svobodně vést své vzdělávání, existuje také alternativa tzv. svobodných a demokratických škol. V České republice funguje Asociace svobodných a demokratických škol, jejímž posláním je sdružovat školy uplatňující principy unschoolingu.[8] Momentálně je na seznamu uvedených 16 škol. Tyto školy často nacházejí inspiraci u zahraničních škol, které se považují za průkopníky tohoto stylu vzdělávání. Jedná se např. o Summerhill a Sudbury.</p>\r\n<p><a href=\"https://dbadmin.webglobe.cz/index.php?route=/sql&amp;pos=0&amp;db=dobrodruzicz1&amp;table=articles\">Wikipedie - Unschooling</a></p>', 1, '2025-04-03 18:51:57', '2025-04-04 08:16:48', 'Vzdělávání', 'Unschooling je přístup ke vzdělávání založený na přesvědčení, že vzdělávání je přirozený celoživotní proces, který probíhá v každé chvíli našeho života.', '1743761808_dítě prozkoumává svět a je zvědavé a rádo se učí (1).jpeg'),
(5, 'Zkušenosti dítěte', 'zkusenosti-ditete', '<p class=\"lead mb-4\">Zvídavost a touha po poznání jsou základními charakteristikami, které nám byly dány od narození. Děti přicházejí na svět s otevřeným srdcem a zvídavými myslmi, plnými zájmu o to, co je obklopuje. Když pozorujeme malé dítě, můžeme vidět, jak se pokouší pochopit různé aspekty světa kolem sebe. Táhnou za nitky, otvírají zásuvky, zkoumají různé povrchy a textury. Všechno je pro ně zábavnou a zároveň vzdělávací hrou.</p>\r\n<p></p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">OBJEVENÍ SVĚTA SKRZE HRU A ZVÍDAVOST</h4>\r\n<p>Hra je pro děti způsobem, jak objevovat, experimentovat a učit se o světě. Přitom se nebojí udělat chybu, protože chápou, že to patří k procesu učení. Hra podporuje jejich kreativitu, rozvíjí motorické dovednosti a učí je spolupracovat s ostatními. Ve skutečnosti je hra pro děti formou neformálního vzdělávání, kde se učí komunikovat, řešit problémy a rozvíjet své myšlení.</p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">ODPOVĚDNOST DĚTÍ A PODPORA JEJICH ROZVOJE</h4>\r\n<p>Respektovat dětskou zvídavost a samostatnost je klíčové pro jejich celkový rozvoj. Když se dítě cítí, že je jeho zvídavost a touha po učení podporována, má větší důvěru v sebe a ve své schopnosti. Dospělí mohou hrát významnou roli tím, že vytvoří bezpečné prostředí, ve kterém mohou děti zkoumat a experimentovat. To zahrnuje nejen fyzický prostor, ale také emocionální podporu a důvěru v jejich schopnosti rozhodovat a učit se samostatně.</p>\r\n<p>Výzva pro dospělé spočívá v tom, aby se nestavěli do role tradičních učitelů, ale spíše do role průvodců a facilitátorů. Dítě má právo na své vlastní zájmy a témata, která ho zajímají, a dospělí by měli být ochotní naslouchat a podporovat tyto zájmy. To neznamená, že by dospělí neměli sdílet své znalosti a zkušenosti, ale měli by to dělat spíše jako partneré na cestě objevování a učení.</p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">KONEC TRADIČNÍ PEDAGOGIKY A VYUŽITÍ POTENCIÁLU</h4>\r\n<p>Je čas opustit rigidní struktury tradiční pedagogiky, která často omezuje děti v jejich schopnosti být samostatnými a kreativními jednotlivci. Děti mají ohromný potenciál pro učení a růst, pokud jim bude poskytnut dostatek prostoru a svobody. Dospělí by měli být průvodci, kteří respektují dětskou autonomii a podporují je v jejich vlastním objevování světa.</p>\r\n<p>Závěrem můžeme konstatovat, že dítě je skutečně člověk se všemi jeho zvídavými a učícími se vlastnostmi. Jeho schopnost objevovat svět skrze hru a zvídavost by měla být respektována a podporována. Dospělí mají povinnost vytvářet prostředí, které umožňuje dětem růst a rozvíjet se jako samostatní a sebevědomí jedinci. Je na čase se odpoutat od tradičního pohledu na pedagogiku a přijmout nový přístup, který klade důraz na dětskou iniciativu, zvídavost a samostatnost.</p>', 1, '2025-04-03 19:02:42', '2025-04-04 08:16:07', 'Vzdělávání', 'Zvídavost a touha po poznání jsou základními charakteristikami, které nám byly dány od narození.', '1743761767_dítě prozkoumává svět a je zvědavé a rádo se učí.jpeg'),
(6, 'Nejčastější komunikační problémy', 'nejcastejsi-komunikacni-problemy', '<p class=\"lead mb-4\">V komunikaci s dětmi se často setkáváme s neefektivními vzory chování, které mohou mít negativní dopad na jejich osobnostní vývoj a vztahy.Jeden z takových vzorů zahrnuje poučování, kritiku a výčitky.</p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">Poučování, kritika a výčitky</h4>\r\n<p>V komunikaci s dětmi se často setkáváme s neefektivními vzory chování, které mohou mít negativní dopad na jejich osobnostní vývoj a vztahy. Jeden z takových vzorů zahrnuje poučování, kritiku a výčitky.</p>\r\n<h4 class=\"mt-5\">Účinnější způsoby komunikace</h4>\r\n<p>Místo poučování a kritiky můžeme zvolit zpětnou vazbu, která je konstruktivní a pozitivní. Například namísto \"Tohle jsi udělal/a špatně!\" můžeme říci: \"Vidím, že tato část můžeš ještě zlepšit, zbytek je skvělý.\" Také můžeme dát prostor dětem pro projevení vlastních názorů a návrhů. Když se snažíme společně dospět k dohodám, cítí se děti zodpovědnější za dodržování pravidel.</p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">Závěr</h4>\r\n<p>Efektivní komunikace s dětmi je klíčová pro jejich rozvoj a budování zdravých vztahů. Místo kritiky a výčitek je vhodné zvolit pozitivní zpětnou vazbu a podporovat děti ve vyjadřování svých názorů. Tím vytváříme prostor pro konstruktivní dialog a posilujeme jejich sebeúctu.</p>\r\n<h4 class=\"mt-5\" style=\"text-align: left;\">Obviňování a emocionální manipulace</h4>\r\n<p>Stále mě kvůli tobě bolí hlava. Je to tím, že jsi tak hlasitý. Jen bych potřeboval/a chvilku klidu, ale ty mi to neumožníš! Pokud si nebudeš sundávat boty, Kája může kvůli tobě mít problémy s dýcháním, víš o jeho astmatu. To budeš mít na svědomí. Jednoho dne mě dovedeš k šílenství. Už mám kvůli vám tolik vrásek. Jednoho dne kvůli vám skončím v nemocnici.</p>\r\n<p>Takové výroky primárně vyvolávají pocit viny. Někteří lidé by mohli tvrdit, že je to v pořádku, protože děti by se měly cítit provinile. Pocity viny však mohou být nebezpečné. Představte si, že matka (nebo učitelka, či partnerka) chce říci něco na způsob: Cítím se vyčerpaná a potřebovala bych trochu pochopení. Namísto toho však volí slova, která může dítě (nebo partner) interpretovat jako obvinění: Ty jsi důvod, proč se cítím špatně nebo proč onemocním!</p>', 1, '2025-04-03 19:07:37', '2025-04-04 08:12:27', 'Vzdělávání', 'V komunikaci s dětmi se často setkáváme s neefektivními vzory chování, které mohou mít negativní dopad na jejich osobnostní vývoj a vztahy.Jeden z takových vzorů zahrnuje poučování, kritiku a výčitky.', '1743761546_chlapec a rodič spolu komunikují a používají nenásilnou komunikaci.jpeg'),
(7, 'Děti jako esence lidství', 'deti-jako-esence-lidstvi', '<p class=\"lead mb-4\">Každé dítě je esencí lidské bytosti, plného zájmu a přirozené touhy rozvíjet se. Od narození je vybaveno schopností pochopit svět kolem sebe. Prostřednictvím zkoumání, hraní, čelících překážkám a vnímání důsledků svých rozhodnutí se dítě stává aktivním účastníkem vlastního vzdělávání. Přirozená zvědavost a touha poznávat je to, co nás vede k objevování a směřování na správnou cestu, kdykoliv čelíme nástrahám života.</p>\r\n<h4 class=\"mt-5\">INDIVIDUÁLNÍ CESTA K SAMOREALIZACI</h4>\r\n<p>Převzetím odpovědnosti za svůj vlastní život, člověk si zachová touhu se rozvíjet, zlepšovat se a vytvářet kvalitní vztahy. To zahrnuje učení se z chyb, stanovování cílů a působení v komunitě se vzájemným respektem. Je to cesta k tomu, aby člověk poznal své pravé já a mohl najít smysl a radost v životě.</p>\r\n<h4 class=\"mt-5\">VE VZDĚLÁNÍ JE SÍLA AUTENTICITY</h4>\r\n<p>Ve světě, kde vzdělání je často vnímáno jako mechanický proces, je zásadní, aby dospělí pochopili hodnotu autentické interakce s dětmi. Když se dospělí zaměřují na osobní růst a sebereflexi, stávají se skutečnými inspiračními postavami pro mladé. Místo toho, abychom vnímali vzdělávání jako jednosměrný proces, bychom měli podporovat otevřený, upřímný a svobodný prostor pro spontánní a přirozené učení.</p>\r\n<h4 class=\"mt-5\">SAMOSTATNOST VE VZDĚLÁVÁNÍ</h4>\r\n<p>V současném vzdělávacím systému je třeba prosazovat větší autonomii. Organizace SvobodaUčení.cz se snaží proměnit vnímání vzdělání v ČR tím, že podporuje unschooling a sebeřízené učení jako legitimní formy vzdělávacích metod. Klíčem k tomuto úsilí je odstranění státních zásahů a regulací ve vzdělání. To by vytvořilo ekosystém, kde by výběr a metoda vzdělání byly plně v rukou jednotlivce a jeho rodiny. V takovém modelu by mohl každý jednotlivec svobodně rozhodnout, jak nejlépe investovat svůj čas a zdroje do vlastního vzdělání.</p>', 1, '2025-04-03 19:09:57', '2025-04-04 08:09:41', 'Vzdělávání', 'Každé dítě je esencí lidské bytosti, plného zájmu a přirozené touhy rozvíjet se. Od narození je vybaveno schopností pochopit svět kolem sebe.', '1743761381_chlapec v motokáře montuje motor a je oblečený do černo žlutého oblečení a je anarchista .jpeg'),
(8, 'Tweety', 'tweety', '<div class=\"container my-5\">\r\n<h2 class=\"mb-4\">Myšlenky a citáty</h2>\r\n<div class=\"row row-cols-1 g-4\">\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Voluntarita tvrdí, že jakékoli vztahy by měly být oboustranně dobrovolné. Extrémní voluntarista nedělá výjimku pro stát.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Vyber si svého otrokáře. <br><small class=\"text-muted\">– Pavol Lupták</small></p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Svoboda lze pouze brát. <br><small class=\"text-muted\">– Pavol Lupták</small></p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Účel nesvětí prostředky. Sátní nedobrovolná demokracie je diktát většiny menšině, avšak já považuji za správné nikoho k ničemu násilím nenutit, dokud si dotyčný hledí svého a nijak útokem neubližuje druhým; a ani když si zásah vůči němu většina demokraticky odhlasuje, neudělá to ze zlé věci dobrou.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Silnější je diktátor. Volební právo by lidé neměli získat v žádném věku. Neexistuje věk, kdy máte právo rozhodovat o druhých, pokud vám nijak neubližují.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Však máte právo bydlet, jen nemá nikdo povinnost vám to bydlení dávat.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">EET řeší důsledek, nikoli příčinu! Daň = špatný systém = neefektivní přerozdělování = všichni platí všechno.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Regulace = rozhoduje o mém majetku i někdo jiný = centrální plánování. Soukromá firma už není soukromá: škola / nemocnice ...</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Daně jsou zlo – nikoli neplatiči! Stačí přestat centrálně přerozdělovat, zrušit daně a vybírat peníze za poskytované služby – stejně jako ostatní firmy.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Lež nelze rozeznat od názoru, tudíž nelze za lež trestat. Lež je záměrné klamání. Názor může být pravdivý nebo nepravdivý. Lež != názor.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Knihy které mi změnily svět: Respektovat a být respektován, Summerhill, Svoboda učení, Nenásilná komunikace, Anarchokapitalismus.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Ti co nechtějí platit daně ≠ že za ty služby nechtějí platit. Chtějí si ty služby vybrat a koupit.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Stát může mít i dvě měny, nebo krytou měnu zlatem či BTC. Jo a nebo by stát mohl přestat vynucovat / určovat násilím co mají lidi používat.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Jako vedoucí skupiny nemusím vynutit jediné pravidlo, protože o všem se musíme dohodnout. Dohoda = všechny strany souhlasí s navrhovaným řešením.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie = rozhodovací systém. Rozhoduje nějaká skupina lidí o komkoli = KO.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie = rozhodovací nástroj. Státní demokracie = organizované násilí.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">„Stát není potřeba.“ Podle BIS se jedná i o terorismus – ohrožení demokratického systému.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Je mi nechutné žít mezi lidmi, co tvrdí že evropské státy jsou civilizované země.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Ve skautu jsem našel přátele, zažil spoustu zážitků, objevil vášeň pro cestování a táboření.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Volit = útok, není to obrana. Použít volební státní systém = někomu něco násilím vnutit.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Víte jak se říká, že máme od státu nějaké služby zdarma? Není to pravda.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Kráva dává mléko? Slepice dává vajíčka? Člověk jim dává najíst? Ne, jsou v zajetí a jsou okrádáni.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Státní soudy nesoudí spravedlivě a nejsou nestranné. Nerozhodují o tom kdo udělal něco zlého či amorálního, rozhodují podle zákonů. Zákony vytvořila nějaká skupina lidí. Policie vynucuje jejich dodržování na lidech co se náchází na území, které si neprávem přivlastňují. #svoboda</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie = rozhodovací nástroj. Státní demokracie = organizované násilí. Demokracie aplikovaná na nedobrovolné účastníky = amorální násilí. Demokracie ≠ svoboda. Státní regulace = většinou útok. Obrana = legitimní regulace. #svoboda #demokracie #eu #stát #ankap #CzechRepublic</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie = rozhodovací nástroj. Státní demokracie = organizované násilí. Demokracie aplikovaná na nedobrovolné účastníky = amorální násilí.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Ak toto v EÚ schvália, tak sa uvidíme v Paraguaji alebo v base.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Byl bych hrdý na Český #stát kdyby nepoužíval útočné násilí ale pouze obranné, nebral lidem zodpovědnost za svůj život, aby stát nekradl lidem peníze, nabízel zákazníkům své služby a nechal si za ně zaplatit, aby dětem nebral základní lidská práva, dodržoval NAP. #ankap</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Byl jsem šťastný, než skončil víkend. Už od narození jsem se rád učil, objevoval, vybíral si výzvy, než se mi do života začal srát stát. Nachystal pro mne devitiletý koncentrák, téměř každý den jsem se bál, stresoval se, bylo mi zle. Nyní hledám cesty, jak se státní agresivitě vyhýbat.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie aplikovaná ve státě je utopie, protože inherentně směřuje k totalitě. Stát postavený na špatných základech nemůže nikdy fungovat, násilí, donucování, rozhodování o druhých, je zkrátka špatný a zlý koncept. Tak to vnímám já. #ankap Stát by jsme mohli změnit jen ve firmu</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Jsem pro vystoupení z České republiky. Klidně sám. Díky že mě necháte. Nemusíte mne nadále chránit, nepřeji si to. Práci i prostředky pro krizi si zajistím, i kdyby ne tak mi stejně pomáhat nemusíte. Za služby si zaplatím sám -&gt; zdravotnictví, soudnictví, policii, školné, hasiče</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Policisté nezabraňují jen špatnostem, oni zkrátka za prachy dělají úplně cokoli na čem se organizovaně domluví hodně lidí. „Demokratické hlasování neudělá ze zlé věci dobrou.“ Bránit živím tvorům pohybovat se po planetě aniž by někomu něco špatného dělali je násilí a útok.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Kapitalista je ten, co si uvědomuje, že má omezené zdroje se kterými může nakládat, a proto mu záleží na penězích. Socialista je ten, co násilím bere druhým, bohatství které nakradl rozdává, a chlubí se tím jak je solidární. Socialista dává z cizího. Kapitalista daruje ze svého.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Muži nesmějí opustit Ukrajinu, rozbít násilím rodinu je špatné, je to agrese. Pokud ostatní státy nemají kapacity přijmout tolik lidí, pak o tom měli rozhodnout ti kteří přijímají, nikoli vláda Ukr. #Stát drží lidi násilím v nebezpečném místě. Děti umřeli protože bez otce nešli..</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Tip na mapu - monitorování radioaktivity: https://remap.jrc.ec.europa.eu/Simple.aspx (Odkaz se může hodit, třeba pro uklidnění nebo pro..)</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Skaut žádal o pomoc. O chvilku později odpovídá Alza @Alzacz , už to vezeme! A pak že kapitalisti jsou nemorální. #Kapitalismus \"je\" dobrovolná směna, která vede k užitku obou stran, aneb vlastnění a uchovávání prostředků za poskytnuté služby. Peníze nejsou špatné. Reklama?Směna!</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Ruský cenzurní úřad nařídil médiím, aby odstranila články, které popisují útok Ruska na Ukrajinu jako \"invazi\", \"útok\" nebo \"vyhlášení války\". Česko zablokoval weby šířící dezinformace týkající se napadení Ukrajiny. Dali jsme naší vládě nástroj k omezování svobody projevu a cenzury!</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Naslouchat odborníkům (nikoli socialistům, kteří si myslí že vaše životy dokážou řídit lépe,) považuji za užitečné. Ať se každý na základě jejich názorů a dat rozhodne. Věřím že není potřeba centrálně řídit za pomocí násilí životy všem. Urč míra nebezpečí je všude, lze se chránit</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Růžový ostrov nebo Insulo de la Rozoj byl krátce existující mikronárod, který vznikl na konci 60. let 20. století na námořní plošině. #esperanto #svoboda Růžový ostrov byl obsazen italskými policejními silami.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Pro mě je #anarchista ten, co odmítání násilně vynucenou poslušnost, naopak respektuje společně (oboustranně) domluvená pravidla. Při porušení dohody/pravidel následuje obrana. Proto anarchista vnímá #stát jako organizované násilí, a který nemá právo téměř nic vymáhat.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">#Stát je organizované násilí Zjistil jsem že, etatisté svoji agresi omlouvají v zájmu zachování bezpečí. Utrpení které způsobují nazývají pouhým nepohodlím. My #Ankap ukazujme že jde bezpečí jednotlivce, lidstva, #ekologie, #oteplování, biodiverzity, zajistit svobodnými principy</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Kdo volí, volí komunisty. #Ankap #nechtenásbýt</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">#Bitcoin je možná ekologičtější než #Fiat měna (#stát-ní peníze). Do výpočtu je třeba zahrnout všechno včetně spotřeby všech bank při jejich provozu - stavby, zaměstnanci. Fiat = #inflace - zadlužení - #chudoba BTC = #ekologie - stabilita - důstojný život https://odlukapenez.cz</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Se světem se něco děje, ty nevíš co to je. Jako každý ses narodil do zajetí. Žiješ ve vězení které vlastně už dávno vůbec nevnímáš. Stát uvěznil tvoji mysl. S červenou kapslí, ti Urza ukáže jak králičí nora hluboko vede. -&gt; urza .cz</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">http://multicharts.com http://interactivebrokers.com https://theice.com https://theice.com</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">„I k totalitě se lze prohlasovat, demokracie ≠ svoboda.“ Volební právo by lidé neměli získat od žádného věku. Neexistuje věk kdy máte právo rozhodovat o druhých pokud Vám nijak neubližují.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-body\">\r\n<p class=\"card-text\">Demokracie dělá z kamaráda s odlišným názorem nepřítele. Demokracie je zlo. Útočné násilí je zlo. Lidé neumí rozlišit co je útočné násilí a co obranné násilí. Myslí si, že když se velká skupina lidí na čemkoli domluví např. rozhodovacím nástrojem \"demokracie\", tak že mohou rozhodovat o jiných lidech a jejich majetku. Obhájí to tím, že jim dají právo hlasovat. Ukradnou území ve jménu bezpečí, nazvou to společenskou smlouvou.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 1, '2025-04-03 19:49:29', '2026-02-16 01:39:26', 'Ankap', 'EET řeší důsledek, nikoli příčinu! Daň = špatný systém = neefektivní přerozdělování = všichni platí všechno.', '1743761329_chlapec v motokáře montuje motor a je oblečený do černo žlutého oblečení a je anarchista  (1).jpeg'),
(9, 'Dobrovolnost místo donucení', 'dobrovolnost-misto-donuceni', '<p style=\"text-align: left;\"></p>\r\n<h4 style=\"text-align: left;\">Úvod: Demokracie jako moderní náboženství</h4>\r\n<p style=\"text-align: left;\">„Voluntarita tvrdí, že jakékoli vztahy by měly být oboustranně dobrovolné. Extrémní voluntarista nedělá výjimku pro stát.“</p>\r\n<p style=\"text-align: left;\"> Vyrůstáme ve společnosti, která nás učí, že demokracie je vrcholem svobody. Volby, parlament, zákony, většina rozhoduje. Jenže čím víc se do toho ponoříš, tím víc si začneš všímat, že něco nehraje. Začněme jedním jednoduchým obrazem: Kráva dává mléko. Slepice dává vajíčka. Člověk jim dává najíst. Vypadá to jako harmonie. Ale je to zajetí. Stejně tak: stát poskytuje silnice, zdravotnictví, vzdělání. Ty mu dáváš daně. Ale jsi v zajetí. Demokracie není svoboda. Je to kolektivní násilí. Demokracie říká, že většina rozhodne. Ale co když nechci být součástí většiny? Co když se rozhodnu žít jinak? Nemůžu. Protože stát si vyhrazuje výsadu násilí. Pokud neplatíš, co si odhlasovali jiní, přijde pokuta. Ignoruj ji – přijde exekutor. Odporuj – přijde policie. Tohle není svoboda. To je nátlak. Lidé, které znáš – přátelé, sousedé – se stávají tvými potenciálními nepřáteli. Ne proto, že by tě chtěli zranit, ale protože prostřednictvím státu prosazují své představy o tom, jak máš žít.</p>\r\n<p style=\"text-align: left;\"></p>\r\n<p style=\"text-align: left;\"></p>\r\n<h4 style=\"text-align: left;\">Násilí: útok vs. obrana Voluntarismus dělí násilí na útočné a obranné. </h4>\r\n<p style=\"text-align: left;\">Útočné násilí znamená, že někomu bereš něco, co mu patří – život, čas, peníze, svobodu.</p>\r\n<p style=\"text-align: left;\"> Obranné násilí znamená, že se bráníš proti agresi. Stát se opírá o útočné násilí – bere ti peníze, i když jsi nikomu neublížil. Nutí tě dodržovat zákony, které jsi nikdy neschválil. A dělá to s celou mašinérií moci. Tohle nelze ospravedlnit. Ani volbami. Ani většinou. Ani „společenskou smlouvou“, kterou nikdo nikdy neviděl ani nepodepsal. Pozitivní vs. negativní práva: skrytá past moderního státu</p>\r\n<p style=\"text-align: left;\">Negativní právo říká: „Nikdo tě nesmí okrást, napadnout, znásilnit.“ Chrání tě před násilím. Negativní právo znamená, mít právo na to abych se mohl vzdělávat a nikdo mi v tom nesmí bránit. Právo aby mi nikdo nebránil bydlet, svatět si dům, pokud tím někoho neohrožuji. </p>\r\n<p style=\"text-align: left;\">Pozitivní právo říká: „Někdo ti musí něco poskytnout.“ Např. zdravotní péči, bydlení, důchod. Zní to ušlechtile. Ale pozor: aby někdo mohl někomu něco poskytnout povinně, musí jinému něco sebrat. A to už je zase násilí. Taková „práva“ jdou přímo proti principu neagrese – proti právu nebýt okrádán. A to vytváří nekonzistence a morální chaos. Pomáhat je správné. Ale jen když je to dobrovolné. Jinak je to jen přerozdělená loupež.</p>\r\n<p style=\"text-align: left;\"></p>\r\n<h4 style=\"text-align: left;\">Společnost bez státu? Funguje to líp, než si myslíš</h4>\r\n<p style=\"text-align: left;\"> „Ale bez státu by byl chaos!“ říká většina. Jenže – kdo říká, že pořádek musí zajišťovat centrální autorita?</p>\r\n<p style=\"text-align: left;\">Pojištění, zdravotní péče, silnice, školy – to všechno může existovat volnotržně. Zákony? Soukromé arbitráže, reputační systémy, komunitní pravidla. Bezpečnost? Dobrovolná spolupráce, lokální ochranné služby – tak jak to často bylo dřív, než stát převzal monopol. Ve všech historických společnostech založených na principu neagrese fungovala překvapivě silná dobrovolná solidarita. Proč? Protože když víš, že nikdo tě nezachrání násilím, pomáháš ostatním – aby příště pomohli oni tobě. Voluntarismus:</p>\r\n<h4 style=\"text-align: left;\">Jednoduché pravidlo pro složitý svět Voluntarismus říká:</h4>\r\n<p style=\"text-align: left;\"><em> Voluntarita tvrdí, že jakékoli vztahy by měly být oboustranně dobrovolné. Voluntarista nedělá vyjímku pro stát.</em></p>\r\n<p style=\"text-align: left;\"> Chceš žít v komunitě s přáteli, podnikat s ostatními, nebo sdílet některé služby? Máš právo si to domluvit s těmi, kdo s tím souhlasí. Dobrovolně, smluvně, bez nátlaku. Chceš žít sám, bez povinností vůči systému, který sis nevybral? Nikdo ti do toho nemá co mluvit. Dokud neničíš, nekradeš a neomezuješ druhé, jsi svobodný člověk. To je anarchokapitalismus. Ne chaos, ale svoboda. Ne bezpráví, ale neagrese. Ne bez solidarity, ale bez donucení. Závěr: Svoboda lze pouze brát Stát se ti snaží říct, že bez něj nejsi nic. Že potřebuješ vládu, vedení, dozor. Ale skutečná svoboda není o volbě mezi A a B ve volbách. Je to o možnosti neúčastnit se vůbec. Nechci nového pána. Nechci lepší stát. Chci žádný stát. A nechci ti nic brát. Jen tě žádám o jediné: Nech mě být.</p>', 1, '2025-04-03 23:31:12', '2025-04-04 08:05:35', 'Ankap', '„Voluntarita tvrdí, že jakékoli vztahy by měly být oboustranně dobrovolné. Extrémní voluntarista nedělá výjimku pro stát.“', '1743761135_chlapec v motokáře montuje motor a je oblečený do černo žlutého oblečení a je anarchista  (2).jpeg');

