le-element\" data-language=\"cs\" data-column=\"content4\" data-id=\"111\">Offer real-time tracking information, so customers can monitor the status of their shipments.</div>\r\n					</p>\r\n				</div>\r\n			</div>\r\n\r\n			<!-- Item -->\r\n			<div class=\"col-sm-6 col-lg-3\">\r\n				<div class=\"card card-body bg-transparent p-0\">\r\n					<div class=\"icon-lg rounded-circle bg-danger bg-opacity-10 text-danger mb-4\">\r\n						<i class=\" bi bi-fire fa-lg\"></i>\r\n					</div>\r\n					<h6>\r\n						<div contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content5\" data-id=\"111\">Returns and exchanges</div>\r\n					</h6>\r\n					<p class=\"mb-0\">\r\n						<div contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content6\" data-id=\"111\">Clearly outline your return and exchange policy, making it easy for customers to initiate returns.</div>\r\n					</p>\r\n\r\n				</div>\r\n			</div>\r\n\r\n			<!-- Item -->\r\n			<div class=\"col-sm-6 col-lg-3\">\r\n				<div class=\"card card-body bg-transparent p-0\">\r\n					<div class=\"icon-lg rounded-circle bg-primary bg-opacity-10 text-primary mb-4\">\r\n						<i class=\" bi bi-headset fa-lg\"></i>\r\n\r\n					</div>\r\n					<h6>\r\n						<div contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content7\" data-id=\"111\">Customer support</div>\r\n					</h6>\r\n					<p class=\"mb-0\">\r\n						<div contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content8\" data-id=\"111\">Provide responsive customer support to address shipping-related queries and issues.</div>\r\n					</p>\r\n				</div>\r\n			</div>\r\n\r\n\r\n			\r\n		</div>\r\n	</div>\r\n</section>\r\nc5\r\n<section class=\"pt-0\">\r\n	<div class=\"container\">\r\n		<div class=\"row g-4 align-items-center\">\r\n			<!-- Image -->\r\n			<div\r\n				class=\"col-lg-6 position-relative\">\r\n				<!-- SVG decoration -->\r\n				<figu